(function(){"use strict";function e(e){const t=(e||"").trim();if(!t)return;window.location.href=`/search/?q=${encodeURIComponent(t)}`}document.addEventListener("DOMContentLoaded",()=>{if(window.location.pathname.replace(/\/$/,"").endsWith("/search"))return;document.querySelectorAll(".search-box-form").forEach(t=>{t.addEventListener("submit",n=>{n.preventDefault();const s=t.querySelector('input[name="q"]');s&&e(s.value)})}),document.querySelectorAll(".search-submit-btn").forEach(t=>{t.addEventListener("click",n=>{n.preventDefault();const s=t.closest("form"),o=s?s.querySelector('input[name="q"]'):null;o&&e(o.value)})})})})()